// 10. MARKSHEET BULK CSV & PDF GENERATORS
function downloadMarksCSVTemplate() {
    let classSel = document.getElementById('marks-class-select');
    let exSel = document.getElementById('marks-exam-type');
    let currentClass = classSel ? classSel.value : 'Nursery';
    let examType = exSel ? exSel.value : 'Unit Test - 1';

    let subjects = getClassSubjects(currentClass, examType);
    let csvHeader = "StudentID,StudentName,RollNo," + subjects.join(",") + "\n";

    let students = getStudents().filter(s => s.studentClass === currentClass);
    students.forEach(s => {
        csvHeader += `"${s.studentId}","${s.name}","${s.rollNo || ''}"` + ",".repeat(subjects.length) + "\n";
    });

    let blob = new Blob([csvHeader], { type: 'text/csv;charset=utf-8;' });
    let link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.setAttribute("download", `Marks_Template_${currentClass}_${examType}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

function importBulkMarksCSV(event) {
    let file = event.target.files[0];
    if (!file) return;

    let classSel = document.getElementById('marks-class-select');
    let exSel = document.getElementById('marks-exam-type');
    let currentClass = classSel ? classSel.value : 'Nursery';
    let examType = exSel ? exSel.value : 'Unit Test - 1';

    let reader = new FileReader();
    reader.onload = function(e) {
        let text = e.target.result;
        let lines = text.split(/\r\n|\n/).filter(l => l.trim() !== '');
        if (lines.length <= 1) { alert("CSV file empty!"); return; }

        let headers = parseCSVLine(lines[0]).map(h => h.trim());
        let records = getMarksRecords();

        for (let i = 1; i < lines.length; i++) {
            let row = parseCSVLine(lines[i]);
            if (row.length < 3) continue;

            let sid = row[0].trim();
            if (!sid) continue;

            let marks = {};
            for (let j = 3; j < headers.length; j++) {
                let sub = headers[j];
                let val = parseFloat(row[j]) || 0;
                marks[sub] = val;
            }

            let idx = records.findIndex(r => r.studentId === sid && r.examType === examType);
            let newRec = { studentId: sid, examType, class: currentClass, marks };
            if (idx !== -1) records[idx] = newRec;
            else records.push(newRec);
        }

        db.ref('marks').set(records).then(() => {
            alert("Bulk Marks Imported Successfully!");
            onStudentOrExamChange();
            renderBulkMarksTable();
        });
    };
    reader.readAsText(file);
}

function exportMarksheetExcel() {
    let classSel = document.getElementById('marks-class-select');
    let exSel = document.getElementById('marks-exam-type');
    let currentClass = classSel ? classSel.value : 'Nursery';
    let examType = exSel ? exSel.value : 'Unit Test - 1';

    let subjects = getClassSubjects(currentClass, examType);
    let csv = "Student ID,Student Name,Class,Roll No," + subjects.join(",") + ",Total Marks\n";

    let students = getStudents().filter(s => s.studentClass === currentClass);
    students.forEach(s => {
        let saved = getSavedMarks(s.studentId, examType);
        let tot = 0;
        let row = `"${s.studentId}","${s.name}","${s.studentClass}","${s.rollNo || '-'}"`;
        subjects.forEach(sub => {
            let val = saved[sub] || 0;
            tot += val;
            row += `,"${val}"`;
        });
        row += `,"${tot}"\n`;
        csv += row;
    });

    let blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    let link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.setAttribute("download", `Marksheet_${currentClass}_${examType}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

