const BANNER_IMAGE_BASE64 = "data:image/png;base64,";

function generateCombinedMarksheetPDF() {
    let stuSel = document.getElementById('marks-student-select');
    if (!stuSel || !stuSel.value) { alert("Select a student first!"); return; }

    let studentId = stuSel.value;
    let students = getStudents();
    let student = students.find(s => s.studentId === studentId);
    if (!student) return;

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();

    // Attach Banner Header Image
    doc.addImage(BANNER_IMAGE_BASE64, 'PNG', 10, 8, 190, 48);

    doc.setFontSize(13);
    doc.setTextColor(0, 0, 0);
    doc.text("PROGRESS REPORT CARD - 2026", 105, 62, { align: "center" });

    doc.setFontSize(10);
    doc.text(`Student Name: ${student.name}`, 14, 72);
    doc.text(`Student ID: ${student.studentId}`, 140, 72);
    doc.text(`Class: ${student.studentClass} (Sec: ${student.section})`, 14, 78);
    doc.text(`Roll No: ${student.rollNo || '-'}`, 140, 78);
    doc.text(`Father's Name: ${student.fatherName || '-'}`, 14, 84);

    let subjects = getClassSubjects(student.studentClass, 'Unit Test - 3');
    let m1 = getSavedMarks(student.studentId, 'Unit Test - 1');
    let m2 = getSavedMarks(student.studentId, 'Unit Test - 2');
    let m3 = getSavedMarks(student.studentId, 'Unit Test - 3');

    let body = [];
    let grandTotal = 0;

    subjects.forEach(sub => {
        let v1 = m1[sub] !== undefined ? parseFloat(m1[sub]) : 0;
        let v2 = m2[sub] !== undefined ? parseFloat(m2[sub]) : 0;
        let v3 = m3[sub] !== undefined ? parseFloat(m3[sub]) : 0;
        let tot = v1 + v2 + v3;
        grandTotal += tot;
        body.push([sub, v1, v2, v3, tot, getGrade(tot)]);
    });

    doc.autoTable({
        startY: 90,
        head: [['Subject', 'Unit-1 (20)', 'Unit-2 (30)', 'Unit-3 (50)', 'Total (100)', 'Grade']],
        body: body
    });

    let finalY = doc.lastAutoTable.finalY + 10;
    doc.setFontSize(11);
    doc.text(`Grand Total Marks Obtained: ${grandTotal}`, 14, finalY);
    doc.text(`Result: ${grandTotal > 0 ? "PASSED" : "PENDING"}`, 140, finalY);

    doc.setFontSize(10);
    doc.text("-------------------------------", 25, finalY + 30);
    doc.text("Class Teacher Signature", 20, finalY + 35);

    doc.text("-------------------------------", 145, finalY + 30);
    doc.text("Principal Signature", 145, finalY + 35);

    doc.save(`Marksheet_${student.name}_${student.studentClass}.pdf`);
}

