function generateBulkAdmitCardsPDF() {
    let classSel = document.getElementById('card-class-select');
    let examName = document.getElementById('card-exam-select').value;
    let selectedClass = classSel ? classSel.value : 'All';

    let students = getStudents();
    if (selectedClass !== 'All') students = students.filter(s => s.studentClass === selectedClass);

    if (students.length === 0) { alert("No students found for Admit Card printing!"); return; }

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });

    // 4 Admit cards per page layout
    for (let i = 0; i < students.length; i += 4) {
        if (i > 0) doc.addPage();

        let positions = [
            { x: 10, y: 8 },   { x: 152, y: 8 },
            { x: 10, y: 106 }, { x: 152, y: 106 }
        ];

        for (let j = 0; j < 4 && (i + j) < students.length; j++) {
            let student = students[i + j];
            let pos = positions[j];
            drawAdmitCardOnPDF(doc, pos, student, examName);
        }
    }

    doc.save(`Bulk_AdmitCards_${selectedClass}_${examName}.pdf`);
}

